{
    /* memset by Space */
    memset(MRASTOLDFT, ' ', sizeof(struct MRASTOLDFT_TAG));
    
    MRASTOLDFT->HIST_SEQ = 0;
    MRASTOLDFT->DEFECT_QTY = 0;
    MRASTOLDFT->CELL_X = 0;
    MRASTOLDFT->CELL_Y = 0;
    MRASTOLDFT->CELL_Z = 0;
    MRASTOLDFT->LOC_X = 0;
    MRASTOLDFT->LOC_Y = 0;
    MRASTOLDFT->LOC_Z = 0;
    MRASTOLDFT->CLEAN_HIST_SEQ = 0;
}


